insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('femur', 'Бедренная кость', 'Os femoris', 'bone', 'Коленная область', 'Длинная трубчатая кость', null, null, null, 'Опора тела и рычаг для мышц бедра; передаёт нагрузку от таза к голени.', 'Медиальный и латеральный мыщелки сочленяются с мыщелками большеберцовой кости; надколенниковая поверхность образует бедренно-надколенниковое сочленение.', 'На дистальном отделе различают медиальный и латеральный мыщелки, надмыщелки и межмыщелковую ямку — место прикрепления крестообразных связок.', '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('patella', 'Надколенник', 'Patella', 'bone', 'Коленная область', 'Сесамовидная кость (крупнейшая в теле)', null, null, null, 'Увеличивает плечо силы четырёхглавой мышцы бедра и защищает переднюю поверхность сустава.', 'Скользит по надколенниковой поверхности бедренной кости при сгибании и разгибании; входит в разгибательный аппарат колена.', 'Располагается в толще сухожилия четырёхглавой мышцы; книзу продолжается связкой надколенника.', '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('tibia', 'Большеберцовая кость', 'Tibia', 'bone', 'Коленная область', 'Длинная трубчатая кость', null, null, null, 'Основная опорная кость голени, несущая весовую нагрузку.', 'Мыщелки (плато) образуют нижнюю суставную поверхность коленного сустава; бугристость — место прикрепления связки надколенника.', 'В межмыщелковых полях прикрепляются крестообразные связки и рога менисков.', '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('fibula', 'Малоберцовая кость', 'Fibula', 'bone', 'Коленная область', 'Длинная трубчатая кость', null, null, null, 'Место прикрепления мышц и связок голени; участвует в стабилизации голеностопного сустава.', 'Не участвует в образовании коленного сустава; к головке прикрепляются малоберцовая коллатеральная связка и двуглавая мышца бедра.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('rectus_femoris', 'Прямая мышца бедра', 'M. rectus femoris', 'muscle', 'Коленная область', 'Мышца передней группы бедра; головка четырёхглавой мышцы; двусуставная', 'Передняя нижняя подвздошная ость (прямая головка) и надвертлужная область (возвратная головка).', 'Через сухожилие четырёхглавой мышцы — к основанию надколенника и далее через связку надколенника к бугристости большеберцовой кости.', 'Бедренный нерв (L2–L4).', 'Разгибание голени в коленном суставе; сгибание бедра в тазобедренном суставе.', 'Пересекает два сустава, поэтому её эффективность при разгибании колена зависит от положения тазобедренного сустава.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('vastus_lateralis', 'Латеральная широкая мышца бедра', 'M. vastus lateralis', 'muscle', 'Коленная область', 'Головка четырёхглавой мышцы бедра; односуставная', 'Большой вертел, верхняя часть межвертельной линии, латеральная губа шероховатой линии.', 'Сухожилие четырёхглавой мышцы, латеральный край надколенника; через связку надколенника — бугристость большеберцовой кости.', 'Бедренный нерв (L2–L4).', 'Разгибание голени в коленном суставе.', 'Крупнейшая головка четырёхглавой мышцы; создаёт латерально направленный компонент тяги на надколенник.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('vastus_medialis', 'Медиальная широкая мышца бедра', 'M. vastus medialis', 'muscle', 'Коленная область', 'Головка четырёхглавой мышцы бедра; односуставная', 'Нижняя часть межвертельной линии, медиальная губа шероховатой линии.', 'Сухожилие четырёхглавой мышцы, медиальный край надколенника; через связку надколенника — бугристость большеберцовой кости.', 'Бедренный нерв (L2–L4).', 'Разгибание голени; участие в медиальной стабилизации надколенника.', 'Косые дистальные волокна противодействуют латеральному смещению надколенника.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('vastus_intermedius', 'Промежуточная широкая мышца бедра', 'M. vastus intermedius', 'muscle', 'Коленная область', 'Головка четырёхглавой мышцы бедра; односуставная', 'Передняя и латеральная поверхности тела бедренной кости.', 'Глубокая часть сухожилия четырёхглавой мышцы; через связку надколенника — бугристость большеберцовой кости.', 'Бедренный нерв (L2–L4).', 'Разгибание голени в коленном суставе.', 'Лежит глубже прямой мышцы бедра, непосредственно на кости.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('biceps_femoris_long', 'Двуглавая мышца бедра (длинная головка)', 'M. biceps femoris, caput longum', 'muscle', 'Коленная область', 'Мышца задней группы бедра (hamstrings); двусуставная', 'Седалищный бугор.', 'Головка малоберцовой кости (общее сухожилие с короткой головкой).', 'Большеберцовая часть седалищного нерва (L5–S2).', 'Сгибание голени и её наружная ротация при согнутом колене; разгибание бедра.', 'Как двусуставная мышца участвует в контроле движения одновременно в тазобедренном и коленном суставах.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('biceps_femoris_short', 'Двуглавая мышца бедра (короткая головка)', 'M. biceps femoris, caput breve', 'muscle', 'Коленная область', 'Мышца задней группы бедра; односуставная', 'Латеральная губа шероховатой линии бедренной кости.', 'Головка малоберцовой кости (общее сухожилие с длинной головкой).', 'Общая малоберцовая часть седалищного нерва (L5–S2).', 'Сгибание голени и её наружная ротация при согнутом колене.', 'Единственная часть задней группы бедра, не пересекающая тазобедренный сустав.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('semitendinosus', 'Полусухожильная мышца', 'M. semitendinosus', 'muscle', 'Коленная область', 'Мышца задней группы бедра; двусуставная', 'Седалищный бугор.', 'Медиальная поверхность проксимального отдела большеберцовой кости (в составе «гусиной лапки»).', 'Большеберцовая часть седалищного нерва (L5–S2).', 'Сгибание голени и её внутренняя ротация при согнутом колене; разгибание бедра.', 'Вместе с портняжной и тонкой мышцами образует «гусиную лапку» на медиальной стороне колена.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('semimembranosus', 'Полуперепончатая мышца', 'M. semimembranosus', 'muscle', 'Коленная область', 'Мышца задней группы бедра; двусуставная', 'Седалищный бугор.', 'Задне-медиальная поверхность медиального мыщелка большеберцовой кости.', 'Большеберцовая часть седалищного нерва (L5–S2).', 'Сгибание голени и её внутренняя ротация; разгибание бедра.', 'Отдаёт волокна к задним отделам капсулы коленного сустава.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('gastrocnemius_medial', 'Икроножная мышца (медиальная головка)', 'M. gastrocnemius, caput mediale', 'muscle', 'Коленная область', 'Мышца задней группы голени; двусуставная', 'Задняя поверхность медиального мыщелка бедренной кости.', 'Пяточный бугор через пяточное (ахиллово) сухожилие.', 'Большеберцовый нерв (S1–S2).', 'Подошвенное сгибание стопы; участие в сгибании голени.', 'Пересекает коленный и голеностопный суставы.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('gastrocnemius_lateral', 'Икроножная мышца (латеральная головка)', 'M. gastrocnemius, caput laterale', 'muscle', 'Коленная область', 'Мышца задней группы голени; двусуставная', 'Задняя поверхность латерального мыщелка бедренной кости.', 'Пяточный бугор через пяточное (ахиллово) сухожилие.', 'Большеберцовый нерв (S1–S2).', 'Подошвенное сгибание стопы; участие в сгибании голени.', 'Пересекает коленный и голеностопный суставы.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('popliteus', 'Подколенная мышца', 'M. popliteus', 'muscle', 'Коленная область', 'Глубокая мышца задней группы голени', 'Латеральная поверхность латерального мыщелка бедренной кости и латеральный мениск.', 'Задняя поверхность большеберцовой кости выше линии камбаловидной мышцы.', 'Большеберцовый нерв (L4–S1).', '«Размыкание» полностью разогнутого колена в начале сгибания; участие в сгибании голени.', 'Обеспечивает ротацию, обратную механизму «замыкания» (screw-home) в конце разгибания.', null, '[{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('sartorius', 'Портняжная мышца', 'M. sartorius', 'muscle', 'Коленная область', 'Мышца передней группы бедра; двусуставная', 'Передняя верхняя подвздошная ость.', 'Медиальная поверхность проксимального отдела большеберцовой кости («гусиная лапка»).', 'Бедренный нерв (L2–L3).', 'Сгибание, отведение и наружная ротация бедра; сгибание голени.', 'Самая длинная мышца тела; компонент «гусиной лапки».', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('gracilis', 'Тонкая мышца', 'M. gracilis', 'muscle', 'Коленная область', 'Мышца медиальной группы бедра; двусуставная', 'Тело и нижняя ветвь лобковой кости.', 'Медиальная поверхность проксимального отдела большеберцовой кости («гусиная лапка»).', 'Запирательный нерв (L2–L3).', 'Приведение бедра; сгибание голени и её внутренняя ротация.', 'Единственная мышца приводящей группы, пересекающая коленный сустав.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('iliotibial_tract', 'Подвздошно-большеберцовый тракт', 'Tractus iliotibialis', 'fascia', 'Коленная область', 'Утолщение широкой фасции бедра', 'Широкая фасция бедра; получает волокна напрягателя широкой фасции и большой ягодичной мышцы.', 'Латеральный мыщелок большеберцовой кости (бугорок Жерди).', 'Собственной иннервации как фасция не имеет; связанные мышцы иннервируются верхним и нижним ягодичными нервами.', 'Латеральная стабилизация тазобедренного и коленного суставов.', 'Передаёт натяжение от мышц таза к латеральной стороне коленного сустава.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('acl', 'Передняя крестообразная связка', 'Lig. cruciatum anterius', 'ligament', 'Коленная область', 'Внутрисуставная связка коленного сустава', 'Задне-медиальная поверхность латерального мыщелка бедренной кости (межмыщелковая ямка).', 'Переднее межмыщелковое поле большеберцовой кости.', null, 'Ограничивает переднее смещение голени относительно бедра; участвует в ротационной стабильности.', 'Натягивается при разгибании; одна из ключевых пассивных стабилизаторов колена.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"}]'::jsonb, false, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('pcl', 'Задняя крестообразная связка', 'Lig. cruciatum posterius', 'ligament', 'Коленная область', 'Внутрисуставная связка коленного сустава', 'Латеральная поверхность медиального мыщелка бедренной кости.', 'Заднее межмыщелковое поле большеберцовой кости.', null, 'Ограничивает заднее смещение голени относительно бедра.', 'Более мощная из двух крестообразных связок.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"}]'::jsonb, false, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('mcl', 'Большеберцовая коллатеральная связка', 'Lig. collaterale tibiale', 'ligament', 'Коленная область', 'Внесуставная связка (медиальная)', 'Медиальный надмыщелок бедренной кости.', 'Медиальная поверхность проксимального отдела большеберцовой кости.', null, 'Противостоит вальгусной нагрузке на коленный сустав.', 'Глубокие волокна связаны с медиальным мениском.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"}]'::jsonb, false, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('lcl', 'Малоберцовая коллатеральная связка', 'Lig. collaterale fibulare', 'ligament', 'Коленная область', 'Внесуставная связка (латеральная)', 'Латеральный надмыщелок бедренной кости.', 'Головка малоберцовой кости.', null, 'Противостоит варусной нагрузке на коленный сустав.', 'Не сращена с латеральным мениском.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"}]'::jsonb, false, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('patellar_ligament', 'Связка надколенника', 'Lig. patellae', 'ligament', 'Коленная область', 'Продолжение сухожилия четырёхглавой мышцы', 'Верхушка надколенника.', 'Бугристость большеберцовой кости.', null, 'Передаёт разгибательное усилие четырёхглавой мышцы на голень.', 'Дистальное звено разгибательного аппарата колена.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"}]'::jsonb, false, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('quadriceps_tendon', 'Сухожилие четырёхглавой мышцы', 'Tendo m. quadricipitis femoris', 'ligament', 'Коленная область', 'Общее сухожилие головок четырёхглавой мышцы', null, 'Основание и края надколенника.', null, 'Передаёт тягу четырёхглавой мышцы на надколенник.', 'Проксимальное звено разгибательного аппарата колена.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"}]'::jsonb, false, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('medial_meniscus', 'Медиальный мениск', 'Meniscus medialis', 'ligament', 'Коленная область', 'С-образная волокнисто-хрящевая пластинка', null, null, null, 'Распределение нагрузки, амортизация, повышение конгруэнтности суставных поверхностей.', 'Менее подвижен, чем латеральный, из-за связи с большеберцовой коллатеральной связкой.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"}]'::jsonb, false, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('lateral_meniscus', 'Латеральный мениск', 'Meniscus lateralis', 'ligament', 'Коленная область', 'Почти кольцевидная волокнисто-хрящевая пластинка', null, null, null, 'Распределение нагрузки и стабилизация латерального отдела сустава.', 'Более подвижен, чем медиальный.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"}]'::jsonb, false, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('talus', 'Таранная кость', 'Talus', 'bone', 'Стопа и голеностоп', 'Кость предплюсны', null, null, null, 'Передаёт нагрузку от голени на стопу.', 'Образует голеностопный сустав с большеберцовой и малоберцовой костями и подтаранный сустав с пяточной; мышцы к ней не прикрепляются.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('calcaneus', 'Пяточная кость', 'Calcaneus', 'bone', 'Стопа и голеностоп', 'Кость предплюсны (самая крупная кость стопы)', null, null, null, 'Задняя опора стопы; рычаг для трёхглавой мышцы голени.', 'К бугру пяточной кости прикрепляется пяточное (ахиллово) сухожилие; от медиального отростка бугра начинаются подошвенный апоневроз и короткие мышцы стопы.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('navicular', 'Ладьевидная кость', 'Os naviculare', 'bone', 'Стопа и голеностоп', 'Кость предплюсны', null, null, null, 'Вершина медиального продольного свода стопы.', 'К бугристости ладьевидной кости прикрепляется задняя большеберцовая мышца — главный динамический «подъёмник» свода.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('cuboid', 'Кубовидная кость', 'Os cuboideum', 'bone', 'Стопа и голеностоп', 'Кость предплюсны', null, null, null, 'Опора латерального края стопы.', 'По её борозде проходит сухожилие длинной малоберцовой мышцы на подошву.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('cuneiforms', 'Клиновидные кости', 'Ossa cuneiformia', 'bone', 'Стопа и голеностоп', 'Три кости предплюсны: медиальная, промежуточная, латеральная', null, null, null, 'Формируют поперечный свод стопы.', 'К медиальной клиновидной кости прикрепляются передняя большеберцовая и длинная малоберцовая мышцы.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('metatarsals', 'Плюсневые кости', 'Ossa metatarsi', 'bone', 'Стопа и голеностоп', 'Пять трубчатых костей плюсны', null, null, null, 'Передняя опора стопы при отталкивании.', 'Головки плюсневых костей принимают нагрузку в фазе переката; при резком росте беговой нагрузки здесь возможны стресс-реакции.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('phalanges', 'Фаланги пальцев стопы', 'Phalanges digitorum pedis', 'bone', 'Стопа и голеностоп', '14 фаланг: у большого пальца две, у остальных по три', null, null, null, 'Участвуют в отталкивании и балансе.', 'Разгибание пальцев при отталкивании натягивает подошвенный апоневроз и поднимает свод (механизм «лебёдки»).', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('soleus', 'Камбаловидная мышца', 'M. soleus', 'muscle', 'Стопа и голеностоп', 'Мышца задней группы голени; часть трёхглавой мышцы голени; односуставная', 'Головка и верхняя треть задней поверхности малоберцовой кости, линия камбаловидной мышцы большеберцовой кости.', 'Через пяточное сухожилие — бугор пяточной кости.', 'Большеберцовый нерв (S1–S2).', 'Подошвенное сгибание стопы; удерживает голень над стопой в опоре.', 'Работает и при согнутом колене, поэтому её тренируют подъёмами на носки с согнутыми коленями.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('calcaneal_tendon', 'Пяточное (ахиллово) сухожилие', 'Tendo calcaneus', 'ligament', 'Стопа и голеностоп', 'Общее сухожилие икроножной и камбаловидной мышц', null, 'Бугор пяточной кости.', null, 'Передаёт усилие трёхглавой мышцы голени при отталкивании.', 'Самое крупное сухожилие тела. Хорошо адаптируется к постепенно растущей нагрузке; резкий рост объёма или скоростной работы — частый фактор перегрузки.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('tibialis_anterior', 'Передняя большеберцовая мышца', 'M. tibialis anterior', 'muscle', 'Стопа и голеностоп', 'Мышца передней группы голени', 'Латеральный мыщелок и верхние 2/3 латеральной поверхности большеберцовой кости, межкостная перепонка.', 'Медиальная клиновидная кость и основание I плюсневой кости.', 'Глубокий малоберцовый нерв (L4–L5).', 'Тыльное сгибание и инверсия стопы.', 'Контролирует опускание стопы после касания пяткой; при перегрузке даёт боль по передней поверхности голени.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('tibialis_posterior', 'Задняя большеберцовая мышца', 'M. tibialis posterior', 'muscle', 'Стопа и голеностоп', 'Глубокая мышца задней группы голени', 'Межкостная перепонка, задние поверхности большеберцовой и малоберцовой костей.', 'Бугристость ладьевидной кости; клиновидные и кубовидная кости, основания II–IV плюсневых.', 'Большеберцовый нерв (L4–L5).', 'Подошвенное сгибание и инверсия стопы.', 'Главный динамический стабилизатор медиального продольного свода.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('fibularis_longus', 'Длинная малоберцовая мышца', 'M. fibularis (peroneus) longus', 'muscle', 'Стопа и голеностоп', 'Мышца латеральной группы голени', 'Головка и верхние 2/3 латеральной поверхности малоберцовой кости.', 'Медиальная клиновидная кость и основание I плюсневой кости (сухожилие проходит по подошве).', 'Поверхностный малоберцовый нерв (L5–S1).', 'Эверсия и подошвенное сгибание стопы.', 'Вместе с передней большеберцовой образует «стремя» под стопой; поддерживает поперечный свод и латеральную стабильность голеностопа.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('fibularis_brevis', 'Короткая малоберцовая мышца', 'M. fibularis (peroneus) brevis', 'muscle', 'Стопа и голеностоп', 'Мышца латеральной группы голени', 'Нижние 2/3 латеральной поверхности малоберцовой кости.', 'Бугристость V плюсневой кости.', 'Поверхностный малоберцовый нерв (L5–S1).', 'Эверсия стопы.', 'Противостоит подворачиванию стопы внутрь — важна для бега по неровному покрытию.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('extensor_digitorum_longus', 'Длинный разгибатель пальцев', 'M. extensor digitorum longus', 'muscle', 'Стопа и голеностоп', 'Мышца передней группы голени', 'Латеральный мыщелок большеберцовой кости, верхние 3/4 малоберцовой кости, межкостная перепонка.', 'Средние и дистальные фаланги II–V пальцев.', 'Глубокий малоберцовый нерв (L5–S1).', 'Разгибание II–V пальцев, тыльное сгибание стопы.', 'Поднимает пальцы в фазе переноса, чтобы стопа не цеплялась за покрытие.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('extensor_hallucis_longus', 'Длинный разгибатель большого пальца', 'M. extensor hallucis longus', 'muscle', 'Стопа и голеностоп', 'Мышца передней группы голени', 'Средняя часть медиальной поверхности малоберцовой кости, межкостная перепонка.', 'Основание дистальной фаланги большого пальца.', 'Глубокий малоберцовый нерв (L5).', 'Разгибание большого пальца, тыльное сгибание стопы.', 'Работает в паре с передней большеберцовой в фазе переноса.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('flexor_digitorum_longus', 'Длинный сгибатель пальцев', 'M. flexor digitorum longus', 'muscle', 'Стопа и голеностоп', 'Глубокая мышца задней группы голени', 'Задняя поверхность большеберцовой кости ниже линии камбаловидной мышцы.', 'Основания дистальных фаланг II–V пальцев.', 'Большеберцовый нерв (S2–S3).', 'Сгибание II–V пальцев, подошвенное сгибание стопы.', 'Помогает удерживать продольный свод и давить пальцами в опору при отталкивании.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('flexor_hallucis_longus', 'Длинный сгибатель большого пальца', 'M. flexor hallucis longus', 'muscle', 'Стопа и голеностоп', 'Глубокая мышца задней группы голени', 'Нижние 2/3 задней поверхности малоберцовой кости, межкостная перепонка.', 'Основание дистальной фаланги большого пальца.', 'Большеберцовый нерв (S2–S3).', 'Сгибание большого пальца, подошвенное сгибание стопы.', 'Важен для мощного отталкивания через большой палец; поддерживает медиальный свод.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('abductor_hallucis', 'Мышца, отводящая большой палец стопы', 'M. abductor hallucis', 'muscle', 'Стопа и голеностоп', 'Собственная мышца стопы (подошвенная, медиальная группа)', 'Медиальный отросток бугра пяточной кости, удерживатель сгибателей, подошвенный апоневроз.', 'Медиальная сторона основания проксимальной фаланги большого пальца.', 'Медиальный подошвенный нерв (S2–S3).', 'Отведение и сгибание большого пальца.', 'Активно работает в упражнении «короткая стопа»; поддерживает медиальный свод — часть «кора стопы».', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"The foot core system: a new paradigm for understanding intrinsic foot muscle function","source":"McKeon P.O. et al. Br J Sports Med, 2015;49(5):290","url":"https://doi.org/10.1136/bjsports-2013-092690"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('flexor_digitorum_brevis', 'Короткий сгибатель пальцев', 'M. flexor digitorum brevis', 'muscle', 'Стопа и голеностоп', 'Собственная мышца стопы (подошвенная, средняя группа)', 'Медиальный отросток бугра пяточной кости, подошвенный апоневроз.', 'Средние фаланги II–V пальцев.', 'Медиальный подошвенный нерв (S2–S3).', 'Сгибание II–V пальцев.', 'Вместе с другими собственными мышцами стопы стабилизирует свод при нагрузке.', null, '[{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"The foot core system: a new paradigm for understanding intrinsic foot muscle function","source":"McKeon P.O. et al. Br J Sports Med, 2015;49(5):290","url":"https://doi.org/10.1136/bjsports-2013-092690"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('long_plantar_ligament', 'Длинная подошвенная связка', 'Lig. plantare longum', 'ligament', 'Стопа и голеностоп', 'Связка подошвы', 'Подошвенная поверхность пяточной кости.', 'Кубовидная кость и основания плюсневых костей.', null, 'Пассивная поддержка латерального продольного свода.', 'Самая длинная связка стопы; работает вместе с подошвенным апоневрозом и мышцами свода.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Clinically Oriented Anatomy, 9th ed.","source":"Moore K.L., Dalley A.F., Agur A.M.R. Wolters Kluwer, 2022"},{"title":"BodyParts3D: 3D structure database for anatomical concepts","source":"Mitsuhashi N. et al. Nucleic Acids Res., 2009","url":"https://doi.org/10.1093/nar/gkn613"}]'::jsonb, true, false) on conflict (id) do nothing;
insert into anatomy_structures (id, name, latin, grp, region, classification, origin, insertion, innervation, function, biomech, notes, "references", has_model, verified) values ('plantar_fascia', 'Подошвенный апоневроз (фасция)', 'Aponeurosis plantaris', 'ligament', 'Стопа и голеностоп', 'Плотная соединительнотканная пластина подошвы', 'Медиальный отросток бугра пяточной кости.', 'Основания проксимальных фаланг пальцев.', null, 'Поддерживает продольный свод; при разгибании пальцев натягивается и поднимает свод (механизм «лебёдки»).', 'Перегрузка проявляется болью в пятке, особенно при первых шагах утром.', null, '[{"title":"Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 42nd ed.","source":"Standring S. (ed.). Elsevier, 2020"},{"title":"Kinesiology of the Musculoskeletal System, 3rd ed.","source":"Neumann D.A. Elsevier, 2017"}]'::jsonb, false, false) on conflict (id) do nothing;
insert into courses (id, title, category, level, description, instructor_id, org_id, duration_min, status, cover, version, is_demo) values ('7c85e7f4-fe93-461d-a7dd-36dc0d6ecfb1', 'Функциональная анатомия коленного сустава', 'Анатомия', 'beginner', 'Кости, мышцы и связки колена на 3D-модели; разгибательный аппарат, двусуставные мышцы, стабилизаторы сустава. Курс включает симуляцию и итоговый тест.', '954fafc3-c3e7-4f1f-a514-949dace2241e', null, 95, 'published', 'teal', 1, true) on conflict (id) do nothing;
insert into courses (id, title, category, level, description, instructor_id, org_id, duration_min, status, cover, version, is_demo) values ('04d5fd66-3d52-491f-a5d0-bc61a33b2e3d', 'Оценка движений и основы корригирующих упражнений', 'Тренерская практика', 'intermediate', 'Как наблюдать базовые движения, фиксировать отклонения и строить логичную корригирующую программу в пределах компетенции тренера. Для тренеров и инструкторов ЛФК.', '954fafc3-c3e7-4f1f-a514-949dace2241e', null, 60, 'published', 'navy', 1, true) on conflict (id) do nothing;
insert into courses (id, title, category, level, description, instructor_id, org_id, duration_min, status, cover, version, is_demo) values ('37354b4b-e7a9-4134-af79-e97300ffca30', 'Реабилитация после реконструкции ПКС: учебный обзор', 'Реабилитация', 'advanced', 'Учебный обзор этапов восстановления после реконструкции передней крестообразной связки. Черновик, находится на медицинской проверке.', '954fafc3-c3e7-4f1f-a514-949dace2241e', null, 45, 'medical_review', 'cyan', 1, true) on conflict (id) do nothing;
