insert into virtual_patients (id, title, status, definition) values ('vp-knee', 'Передняя боль в колене у бегуньи-любительницы', 'published', '{"patient":{"alias":"Пациент А.","age":29,"sex":"ж","occupation":"Офисный сотрудник, бег-любитель"},"scenario":"Пациентка жалуется на тупую боль спереди правого колена, которая усиливается при беге и спуске по лестнице. Задача — собрать анамнез, запросить данные обследования и разобрать анатомическую логику случая.","objectives":["Отличать значимые вопросы анамнеза от второстепенных","Связывать характер нагрузки с анатомическими структурами","Распознавать отсутствие «красных флагов» и понимать, когда нужен врач"],"anatomy":["patella","rectus_femoris","vastus_medialis","vastus_lateralis","iliotibial_tract"],"history":[{"id":"h1","q":"Где именно болит?","a":"Спереди, вокруг и за надколенником.","relevant":true},{"id":"h2","q":"Когда боль усиливается?","a":"При беге, спуске по лестнице, после долгого сидения с согнутыми коленями.","relevant":true},{"id":"h3","q":"Была ли травма?","a":"Нет, травмы не было, боль появилась постепенно.","relevant":true},{"id":"h4","q":"Менялась ли недавно нагрузка?","a":"Да, за последний месяц увеличила беговой объём примерно вдвое, готовясь к полумарафону.","relevant":true},{"id":"h5","q":"Есть ли отёк, ночная боль, повышение температуры, онемение?","a":"Нет, ничего такого нет.","relevant":true},{"id":"h6","q":"Какой у вас любимый цвет кроссовок?","a":"Синий.","relevant":false},{"id":"h7","q":"Сколько часов вы спите?","a":"Около 7 часов.","relevant":false}],"exams":[{"id":"e1","name":"Осмотр и пальпация","finding":"Отёка нет. Болезненность при пальпации по краям надколенника.","relevant":true},{"id":"e2","name":"Приседание на одной ноге","finding":"Воспроизводит знакомую боль; колено смещается внутрь, таз опускается на противоположной стороне.","relevant":true},{"id":"e3","name":"Сила отводящих мышц бедра (мануальное тестирование)","finding":"Справа заметно слабее, чем слева.","relevant":true},{"id":"e4","name":"Тесты стабильности связок колена","finding":"Без особенностей, связочный аппарат стабилен.","relevant":true},{"id":"e5","name":"Измерение окружности запястья","finding":"Без особенностей.","relevant":false}],"questions":[{"id":"p1","prompt":"С каким сочленением анатомически связана описанная локализация боли?","options":[{"id":"a","text":"Бедренно-надколенниковое сочленение","correct":true,"feedback":"Боль спереди, за надколенником, усиливающаяся при нагрузке в сгибании, анатомически связана с бедренно-надколенниковым сочленением."},{"id":"b","text":"Проксимальное межберцовое сочленение","correct":false,"feedback":"Межберцовое сочленение расположено латерально и ниже — не соответствует локализации."},{"id":"c","text":"Тазобедренный сустав","correct":false,"feedback":"Тазобедренный сустав не соответствует локализации жалобы."}]},{"id":"p2","prompt":"Какой фактор анамнеза наиболее важен для понимания нагрузки на ткани?","options":[{"id":"a","text":"Резкое увеличение бегового объёма","correct":true,"feedback":"Быстрый рост нагрузки — частый фактор перегрузки тканей; это ключевая находка анамнеза."},{"id":"b","text":"Цвет кроссовок","correct":false,"feedback":"Не имеет значения для анализа случая."},{"id":"c","text":"Продолжительность сна 7 часов","correct":false,"feedback":"Сон важен для восстановления, но 7 часов — не ключевой фактор в этом случае."}]},{"id":"p3","prompt":"Указывают ли собранные данные на «красные флаги», требующие срочного направления к врачу?","options":[{"id":"a","text":"Нет: нет травмы, отёка, ночной боли, лихорадки и неврологических симптомов","correct":true,"feedback":"Верно. Однако при появлении таких признаков или отсутствии улучшения нужна консультация врача."},{"id":"b","text":"Да, болезненность при пальпации — красный флаг","correct":false,"feedback":"Локальная болезненность сама по себе не является красным флагом."}]},{"id":"p4","prompt":"Слабость какой мышцы может объяснить опускание таза и смещение колена внутрь при приседании на одной ноге?","options":[{"id":"a","text":"Средней ягодичной мышцы","correct":true,"feedback":"Средняя ягодичная мышца — главный отводящий мускул бедра и стабилизатор таза во фронтальной плоскости."},{"id":"b","text":"Икроножной мышцы","correct":false,"feedback":"Икроножная мышца не контролирует положение таза во фронтальной плоскости."},{"id":"c","text":"Передней большеберцовой мышцы","correct":false,"feedback":"Передняя большеберцовая мышца — разгибатель стопы."}]}]}'::jsonb) on conflict (id) do nothing;
insert into assessments (id, title, course_id, author_id, passing_score, max_attempts, time_limit_min, randomize, feedback, status) values ('b1480465-dcc6-4ecc-a88b-7220d25f1305', 'Итоговый тест: функциональная анатомия колена', '7c85e7f4-fe93-461d-a7dd-36dc0d6ecfb1', '954fafc3-c3e7-4f1f-a514-949dace2241e', 70, 3, 15, true, 'after', 'published') on conflict (id) do nothing;
insert into assessments (id, title, course_id, author_id, passing_score, max_attempts, time_limit_min, randomize, feedback, status) values ('9240887b-64de-47bd-ab09-5f8c17d9b5fc', 'Тест: оценка движений и корригирующие упражнения', '04d5fd66-3d52-491f-a5d0-bc61a33b2e3d', '954fafc3-c3e7-4f1f-a514-949dace2241e', 70, 3, 10, false, 'immediate', 'published') on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('05794cef-c959-421b-a5f8-af3bf68869a1', 'b1480465-dcc6-4ecc-a88b-7220d25f1305', 'single', 'Какая головка четырёхглавой мышцы бедра пересекает и тазобедренный, и коленный суставы?', null, null, '[{"id":"a","text":"Прямая мышца бедра","correct":true},{"id":"b","text":"Латеральная широкая мышца бедра","correct":false},{"id":"c","text":"Медиальная широкая мышца бедра","correct":false},{"id":"d","text":"Промежуточная широкая мышца бедра","correct":false}]'::jsonb, null, null, 'Прямая мышца бедра начинается от передней нижней подвздошной ости, поэтому сгибает бедро и разгибает голень. Три широкие мышцы начинаются от бедренной кости и действуют только на коленный сустав.', 1, 1) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('85781cbb-ca36-484e-a06f-afb4fb752e3e', 'b1480465-dcc6-4ecc-a88b-7220d25f1305', 'multi', 'Какие мышцы относятся к группе задних мышц бедра (хамстрингов)?', null, null, '[{"id":"a","text":"Полусухожильная мышца","correct":true},{"id":"b","text":"Полуперепончатая мышца","correct":true},{"id":"c","text":"Длинная головка двуглавой мышцы бедра","correct":true},{"id":"d","text":"Портняжная мышца","correct":false},{"id":"e","text":"Подколенная мышца","correct":false}]'::jsonb, null, null, 'Классические хамстринги — полусухожильная, полуперепончатая и длинная головка двуглавой мышцы бедра: они начинаются от седалищного бугра и пересекают два сустава. Портняжная мышца относится к передней группе, подколенная — к задней группе голени.', 2, 2) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('267cff59-7d82-4eea-a416-5a04492ae3f0', 'b1480465-dcc6-4ecc-a88b-7220d25f1305', 'match', 'Сопоставьте связку с её основной стабилизирующей функцией.', null, null, null, '[{"left":"Передняя крестообразная связка","right":"Ограничивает переднее смещение голени относительно бедра"},{"left":"Задняя крестообразная связка","right":"Ограничивает заднее смещение голени относительно бедра"},{"left":"Большеберцовая коллатеральная связка","right":"Противостоит вальгусной нагрузке"},{"left":"Малоберцовая коллатеральная связка","right":"Противостоит варусной нагрузке"}]'::jsonb, null, 'Крестообразные связки контролируют переднезаднюю стабильность, коллатеральные — фронтальную (варус/вальгус).', 2, 3) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('e48000a3-1b72-4227-ab6e-779d8aa555d0', 'b1480465-dcc6-4ecc-a88b-7220d25f1305', 'sequence', 'Расположите элементы разгибательного аппарата колена от проксимального к дистальному.', null, null, null, null, '["Четырёхглавая мышца бедра","Сухожилие четырёхглавой мышцы","Надколенник","Связка надколенника","Бугристость большеберцовой кости"]'::jsonb, 'Тяга четырёхглавой мышцы передаётся через её сухожилие на надколенник, далее через связку надколенника на бугристость большеберцовой кости.', 2, 4) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('e15a1bf7-d076-4f2b-a607-15bba6623ec5', 'b1480465-dcc6-4ecc-a88b-7220d25f1305', 'identify', 'Определите кость, выделенную на 3D-модели.', null, 'fibula', '[{"id":"a","text":"Малоберцовая кость","correct":true},{"id":"b","text":"Большеберцовая кость","correct":false},{"id":"c","text":"Надколенник","correct":false},{"id":"d","text":"Бедренная кость","correct":false}]'::jsonb, null, null, 'Выделена малоберцовая кость. Она не образует коленный сустав, но её головка — место прикрепления малоберцовой коллатеральной связки и двуглавой мышцы бедра.', 1, 5) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('a70cf934-9d7c-46e7-ab80-2a2f2a92c380', 'b1480465-dcc6-4ecc-a88b-7220d25f1305', 'case', 'Какая связка в первую очередь противостоит такому механизму нагрузки?', 'Учебный случай (синтетический): футболист 22 лет получил удар по латеральной поверхности колена при опорной ноге. Колено отклонилось внутрь (вальгусная нагрузка).', null, '[{"id":"a","text":"Большеберцовая (медиальная) коллатеральная связка","correct":true},{"id":"b","text":"Малоберцовая (латеральная) коллатеральная связка","correct":false},{"id":"c","text":"Задняя крестообразная связка","correct":false},{"id":"d","text":"Связка надколенника","correct":false}]'::jsonb, null, null, 'Удар снаружи создаёт вальгусную нагрузку и растягивает медиальные структуры; первичный ограничитель — медиальная коллатеральная связка. Это учебный пример анатомической логики, а не диагностический алгоритм.', 2, 6) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('db49dfbe-04bf-40d2-ab1a-dd96caba7ccc', 'b1480465-dcc6-4ecc-a88b-7220d25f1305', 'single', 'Какой нерв иннервирует четырёхглавую мышцу бедра?', null, null, '[{"id":"a","text":"Бедренный нерв","correct":true},{"id":"b","text":"Седалищный нерв","correct":false},{"id":"c","text":"Запирательный нерв","correct":false},{"id":"d","text":"Большеберцовый нерв","correct":false}]'::jsonb, null, null, 'Все четыре головки четырёхглавой мышцы иннервирует бедренный нерв (L2–L4).', 1, 7) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('5c523de7-0857-480f-add2-e74369056ee0', 'b1480465-dcc6-4ecc-a88b-7220d25f1305', 'single', 'Какая мышца «разблокирует» полностью разогнутое колено в начале сгибания?', null, null, '[{"id":"a","text":"Подколенная мышца","correct":true},{"id":"b","text":"Икроножная мышца","correct":false},{"id":"c","text":"Портняжная мышца","correct":false},{"id":"d","text":"Тонкая мышца","correct":false}]'::jsonb, null, null, 'Подколенная мышца ротирует большеберцовую кость внутрь (или бедро наружу при опорной ноге), снимая механизм «замыкания» колена.', 1, 8) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('5866cc9e-7df0-4bde-a48b-23f0744dd879', '9240887b-64de-47bd-ab09-5f8c17d9b5fc', 'single', 'Что из перечисленного является целью первичной оценки движений перед составлением программы упражнений?', null, null, '[{"id":"a","text":"Выявить двигательные паттерны и ограничения, которые важно учесть при выборе упражнений","correct":true},{"id":"b","text":"Поставить медицинский диагноз","correct":false},{"id":"c","text":"Определить максимальный вес в упражнении","correct":false}]'::jsonb, null, null, 'Оценка движений помогает выбрать и адаптировать упражнения. Постановка диагноза не входит в компетенцию тренера и выходит за рамки этого курса.', 1, 9) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('cda904d6-13dd-4db7-a50b-58b57c3232cb', '9240887b-64de-47bd-ab09-5f8c17d9b5fc', 'multi', 'Какие наблюдения при выполнении приседа обычно фиксируют при визуальной оценке?', null, null, '[{"id":"a","text":"Смещение коленей внутрь (вальгус)","correct":true},{"id":"b","text":"Отрыв пяток от пола","correct":true},{"id":"c","text":"Чрезмерный наклон туловища вперёд","correct":true},{"id":"d","text":"Цвет кожи голени","correct":false}]'::jsonb, null, null, 'Типичные точки наблюдения — стопы, колени, таз и туловище. Наблюдения описывают движение, но не объясняют однозначно его причину.', 2, 10) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('f0a6a095-366f-403f-a29a-09e679fd8437', '9240887b-64de-47bd-ab09-5f8c17d9b5fc', 'sequence', 'Расположите этапы корригирующей программы в логичном порядке.', null, null, null, null, '["Оценка движения","Снижение избыточной активности / мобилизация","Активация недостаточно активных мышц","Интеграция в целостное движение","Повторная оценка"]'::jsonb, 'Распространённая учебная логика: оценить → подготовить ткани → активировать → интегрировать → переоценить.', 2, 11) on conflict (id) do nothing;
insert into questions (id, assessment_id, type, prompt, case_text, structure_id, options, pairs, sequence, explanation, points, position) values ('1ca3d7b5-e161-4daa-a538-56eb1e6b0cf5', '9240887b-64de-47bd-ab09-5f8c17d9b5fc', 'case', 'Какое действие тренера корректно?', 'Учебный случай (синтетический): клиент сообщает о внезапно появившемся онемении в ноге и ночной боли, не связанной с нагрузкой.', null, '[{"id":"a","text":"Прекратить работу с этой жалобой и рекомендовать обратиться к врачу","correct":true},{"id":"b","text":"Подобрать растяжку для снятия онемения","correct":false},{"id":"c","text":"Увеличить нагрузку, чтобы «разогреть» мышцы","correct":false}]'::jsonb, null, null, 'Неврологические симптомы и ночная боль — «красные флаги», требующие направления к врачу. Тренер не диагностирует и не лечит.', 2, 12) on conflict (id) do nothing;
insert into lessons (id, course_id, module_id, title, type, body, video_url, file_url, simulation_id, assessment_id, anatomy_focus, duration_min, position) values ('cfac0bb6-3c74-44ba-ac6d-5d0c1ce04fa3', '7c85e7f4-fe93-461d-a7dd-36dc0d6ecfb1', '34146ac0-1310-4bfd-a61b-958b8305ccee', 'Строение коленного сустава', 'text', 'Коленный сустав — самый крупный синовиальный сустав тела. В нём выделяют два сочленения:
insert into lessons (id, course_id, module_id, title, type, body, video_url, file_url, simulation_id, assessment_id, anatomy_focus, duration_min, position) values ('76f3a2f0-c4c5-446b-aee8-b6722be9770a', '7c85e7f4-fe93-461d-a7dd-36dc0d6ecfb1', '34146ac0-1310-4bfd-a61b-958b8305ccee', '3D-практикум: кости колена', 'anatomy', 'Откройте 3D-модель, найдите бедренную, большеберцовую, малоберцовую кости и надколенник. Используйте «Изолировать», чтобы рассмотреть каждую кость отдельно.', null, null, null, null, array['femur','tibia','fibula','patella']::text[], 10, 2) on conflict (id) do nothing;
