insert into lessons (id, course_id, module_id, title, type, body, video_url, file_url, simulation_id, assessment_id, anatomy_focus, duration_min, position) values ('b4000f09-0694-4118-a161-ac2c70ac5a75', '7c85e7f4-fe93-461d-a7dd-36dc0d6ecfb1', '50e43d4f-bdf6-4fc7-aa40-101bb788b069', '3D-практикум: мышцы бедра', 'anatomy', 'Найдите на модели головки четырёхглавой мышцы и задние мышцы бедра. Сравните точки начала односуставных и двусуставных мышц.', null, null, null, null, array['rectus_femoris','vastus_lateralis','vastus_medialis','semitendinosus','biceps_femoris_long','popliteus']::text[], 10, 2) on conflict (id) do nothing;
