insert into lessons (id, course_id, module_id, title, type, body, video_url, file_url, simulation_id, assessment_id, anatomy_focus, duration_min, position) values ('a5a2fe79-cdee-44d4-ab7e-87721d36e7ba', '7c85e7f4-fe93-461d-a7dd-36dc0d6ecfb1', 'b6af7166-a95b-49fc-a81f-b749098086ba', 'Итоговый тест', 'quiz', 'Итоговый тест курса. Проходной балл — 70%. Для получения сертификата необходимо пройти все уроки и сдать тест.', null, null, null, 'b1480465-dcc6-4ecc-a88b-7220d25f1305', array[]::text[], 15, 4) on conflict (id) do nothing;
insert into lessons (id, course_id, module_id, title, type, body, video_url, file_url, simulation_id, assessment_id, anatomy_focus, duration_min, position) values ('546b11f0-8abb-42cf-ade0-1ebbc78a2ce9', '04d5fd66-3d52-491f-a5d0-bc61a33b2e3d', '012a4129-964a-4e1d-a851-87114f7b0380', 'Зачем оценивать движения', 'text', 'Оценка движений помогает тренеру выбрать упражнения, подходящие конкретному человеку, и отслеживать изменения.
