insert into lessons (id, course_id, module_id, title, type, body, video_url, file_url, simulation_id, assessment_id, anatomy_focus, duration_min, position) values ('3863262f-6778-45f1-abc5-4e8946410fb0', '37354b4b-e7a9-4134-af79-e97300ffca30', '456bf116-6c85-4edd-ae4a-3bad859212e9', 'ПКС: анатомия и функция', 'text', 'Черновик урока. Передняя крестообразная связка идёт от латерального мыщелка бедра к переднему межмыщелковому полю большеберцовой кости…', null, null, null, null, array[]::text[], 15, 1) on conflict (id) do nothing;
